target.css:
:root {
  --ink: #193343;
  --muted: #67808b;
  --line: #d5e2e5;
  --paper: #ffffff;
  --wash: #eef7f6;
  --deep: #16485a;
  --coral: #e76f5b;
  --blue: #4389ba;
  --mint: #4ca889;
  --gold: #e6ad45;
  --ok-bg: #dff2e8;
}

* {
  box-sizing: border-box;
}

.centrifuge-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 12px;
}

.lab-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--paper);
  background: var(--deep);
  border-radius: 10px;
  font-size: 20px;
}

.title-group {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 19px;
  line-height: 1.15;
}

.live-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  color: var(--mint);
  background: var(--ok-bg);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.4px;
}

.live-badge i {
  width: 6px;
  height: 6px;
  background: var(--mint);
  border-radius: 50%;
}

.run-strip {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 9px 16px;
  color: var(--paper);
  background: var(--deep);
}

.run-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.run-strip strong {
  font-size: 17px;
  letter-spacing: 0.5px;
}

.rpm {
  margin-left: auto;
  color: var(--line);
  font-size: 11px;
  font-weight: 700;
}

.monitor-grid {
  display: grid;
  grid-template-columns: 178px 1fr;
  gap: 16px;
  padding: 14px 16px;
}

.rotor-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin: 0;
  padding: 10px;
  background: var(--wash);
  border-radius: 12px;
}

.rotor {
  position: relative;
  width: 88px;
  height: 88px;
  border: 8px solid var(--deep);
  border-radius: 50%;
}

.rotor b {
  position: absolute;
  inset: 20px;
  display: grid;
  place-items: center;
  color: var(--paper);
  background: var(--deep);
  border-radius: 50%;
  font-size: 12px;
}

.tube {
  position: absolute;
  z-index: 1;
  width: 15px;
  height: 23px;
  border: 3px solid var(--paper);
  border-radius: 5px;
}

.tube-a { top: -12px; left: 29px; background: var(--coral); }
.tube-b { top: 25px; right: -12px; background: var(--blue); }
.tube-c { bottom: -12px; left: 29px; background: var(--mint); }
.tube-d { top: 25px; left: -12px; background: var(--gold); }

figcaption {
  color: var(--muted);
  font-size: 10px;
  text-align: center;
}

figcaption span {
  display: block;
  margin-top: 2px;
  color: var(--mint);
  font-weight: 800;
}

.sample-panel {
  min-width: 0;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

h2 {
  margin-bottom: 0;
  font-size: 14px;
}

.panel-heading span {
  color: var(--muted);
  font-size: 10px;
}

.sample-list {
  display: grid;
  gap: 4px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.sample-list li {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 4px 6px;
  background: var(--wash);
  border-radius: 6px;
  font-size: 11px;
}

.sample-list li span:last-child {
  color: var(--muted);
  font-weight: 700;
}

.sample-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.coral { background: var(--coral); }
.blue { background: var(--blue); }
.mint { background: var(--mint); }
.gold { background: var(--gold); }

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 11px;
}

.check {
  color: var(--mint);
  font-weight: 900;
}

button {
  padding: 7px 10px;
  color: var(--deep);
  background: var(--paper);
  border: 1px solid var(--deep);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

